import React from 'react';

function Banner({ selectedCategory = "ALL", setSelectedCategory }) {
  const categories = ["ALL", "Clothing", "Footwear", "Accessories", "Gadgets", "Books"];

  return (
    <div className="bannerParentDiv" style={{ backgroundColor: '#002f34', color: 'white', padding: '12px 20px' }}>
      <div className="bannerChildDiv" style={{ display: 'flex', gap: '25px', alignItems: 'center', fontSize: '14px', flexWrap: 'wrap' }}>
        {categories.map((cat) => (
          <span
            key={cat}
            onClick={() => setSelectedCategory && setSelectedCategory(cat)}
            style={{
              cursor: 'pointer',
              fontWeight: selectedCategory === cat ? 'bold' : 'normal',
              textDecoration: selectedCategory === cat ? 'underline' : 'none',
              color: selectedCategory === cat ? '#ffce32' : 'white'
            }}
          >
            {cat === "ALL" ? "ALL CATEGORIES" : cat}
          </span>
        ))}
      </div>
    </div>
  );
}

export default Banner;
